mapper.select:
SELECT t1.`id`, t1.`task_name`, t1.`task_time`, t1.`application_code`, t1.`application_name`, t1.`business_key`, t1.`business_type`, t1.`business_type_name`, t1.`business_status`, t1.`business_status_name`, t1.`business_principal`, t1.`status`, t1.`url`, t1.`task_del_state` FROM `todo_task` t1 INNER JOIN `todo_person` t2 on t1.`id` = t2.`todo_task_id`
t2.`user_id` = #{userId} and t1.`status` = 'TODO' and t1.`task_del_state` = 0
and t1.`task_name` like concat('%',#{param.keyword},'%')
and t1.`business_type` in
#{businessType}
and t1.`task_time` >= #{param.period.begin}
and t1.`task_time` <= #{param.period.end}
order by t1.`task_time` DESC

SELECT t1.`id`, t1.`task_name`, t1.`task_time`, t1.`application_code`, t1.`application_name`, t1.`business_key`, t1.`business_type`, t1.`business_type_name`, t1.`business_status`, t1.`business_status_name`, t1.`next_business_status`, t1.`next_business_status_name`, t1.`business_principal`, t1.`handler_time`, t1.`status`, t1.`url`, t1.`task_del_state` FROM `todo_task` t1 INNER JOIN `todo_person` t2 on t1.`id` = t2.`todo_task_id`
t2.`user_id` = #{userId} and t1.`status` = 'DONE' and t2.`status` = 'DONE' and t1.`task_del_state` = 0
and t1.`task_name` like concat('%',#{param.keyword},'%')
and t1.`business_type` in
#{businessType}
and t1.`task_time` >= #{param.period.begin}
and t1.`task_time` <= #{param.period.end}
order by t1.`task_time` desc

SELECT count(t1.`id`) as total FROM `todo_task` t1
t1.`status` = 'TODO' and t1.`task_del_state` = 0
and t1.`task_time` >= #{period.begin}
and t1.`task_time` <= #{period.end}

SELECT t1.`business_type`, t1.`business_type_name`, count(t1.`id`) as total FROM `todo_task` t1
t1.`status` = 'TODO' and t1.`task_del_state` = 0
and t1.`task_time` >= #{period.begin}
and t1.`task_time` <= #{period.end}
group by t1.`business_type`

SELECT DATE_FORMAT(t1.`task_time`,'%Y-%m-%d') as period, COUNT(t1.`id`) as total FROM `todo_task` t1 INNER JOIN `todo_person` t2 on t1.`id` = t2.`todo_task_id`
t2.`user_id` = #{userId} and ((t1.`status` = 'TODO' and t1.`task_del_state` = 0) or (t1.`status` = 'DONE' and t2.`status` = 'TODO'))
and t1.`task_time` >= #{period.begin}
and t1.`task_time` <= #{period.end}
GROUP BY DATE_FORMAT(t1.`task_time`,'%Y-%m-%d')

SELECT count(DISTINCT t1.`id`) AS number, t3.todo_tag_code as type FROM `todo_task` t1 INNER JOIN `todo_person` t2 ON t2.`todo_task_id` = t1.`id` INNER JOIN todo_tag_refer_business_type t3 ON t3.business_type = t1.business_type
t1.`task_del_state` = 0
and t1.`status` = #{status} and t2.`status` = #{status}
and t1.`task_time` >= #{param.period.begin}
and t1.`task_time` <= #{param.period.end}
GROUP BY t3.todo_tag_code

SELECT t1.`id`, t1.`task_name`, t1.`task_time`, t1.`application_code`, t1.`application_name`, t1.`business_key`, t1.`business_type`, t1.`business_type_name`, t1.`business_status`, t1.`business_status_name`, t1.`next_business_status`, t1.`next_business_status_name`, t1.`business_principal`, t1.`handler_time`, t1.`status`, t1.`url`, t1.`task_del_state` FROM `todo_task` t1 INNER JOIN `todo_person` t2 on t1.`id` = t2.`todo_task_id`
t1.`task_del_state` = 0
and t1.`status` = #{param.status} and t2.`status` = #{param.status}
and t1.`status` = t2.`status`
and t1.`create_by` = #{param.createBy}
and t1.`task_name` like concat('%',#{param.keyword},'%')
and t1.`business_type` in
#{businessType}
and t1.`task_time` >= #{param.period.begin}
and t1.`task_time` <= #{param.period.end}
order by t1.`task_time` desc

SELECT
count(DISTINCT t1.`id`) AS totalNum
FROM
`todo_task` t1
INNER JOIN `todo_person` t2 on t1.`id` = t2.`todo_task_id`
inner join `todo_tag_refer_business_type` t3 on t1.`business_type` = t3.`business_type`

    t1.`task_del_state` = 0

        and t1.`task_time` >= #{param.period.begin}


        and t1.`task_time` <= #{param.period.end}


        and t1.`status` = #{param.status}


        and t1.`business_type` in

            #{businessType}



        and t3.todo_tag_code = #{param.todoTagCode}


        and t2.`user_id` = #{param.userId}
